arguments.command:
cd /tmp/vally-eval-trial-yFU9ML && python3 - <<'E'
p='payment-integration-test/pom.xml'
s=open(p).read()
s=s.replace("""    <dependency>
      <groupId>org.assertj""","""    <dependency>
      <groupId>com.tngtech.archunit</groupId>
      <artifactId>archunit-junit5</artifactId>
      <version>1.4.0</version>
      <scope>test</scope>
    </dependency>
    <dependency>
      <groupId>org.assertj""",1)
open(p,'w').write(s)
E
d=payment-integration-test/src/test/java/com/example/payment/integrationtest/architecture; mkdir -p $d
cat > $d/LayerDependencyTest.java <<'E'
package com.example.payment.integrationtest.architecture;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;

import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayerDependencyTest {

    private static final String DOMAIN = "com.example.payment.domain..";
    private static final String APPLICATION = "com.example.payment.application..";

    @ArchTest
    static final ArchRule domainDependsOnlyOnItselfAndLanguageCore = classes()
            .that().resideInAPackage(DOMAIN)
            .should().onlyDependOnClassesThat().resideInAnyPackage(
                    DOMAIN, "java.lang..", "java.math..", "java.util..");

    @ArchTest
    static final ArchRule applicationDependsOnlyOnDomainAndLanguageCore = classes()
            .that().resideInAPackage(APPLICATION)
            .should().onlyDependOnClassesThat().resideInAnyPackage(
                    APPLICATION, DOMAIN, "java.lang..", "java.math..", "java.util..");
}
E
mvn -q -o verify 2>&1 | tail -30

